package brd14

// The repository's shared corpus, asserted from Go.
//
// contract_test.go carries the frozen literals inline, so the published module
// proves the contract on its own. This file adds the corpus every other
// implementation in the repository asserts too: vectors/*.tsv, generated by
// tools/vectorgen.py from tools/oracle.py — an arbitrary-precision oracle that
// shares no algorithm with this package. Thousands of rows instead of dozens,
// and, for every refusal, the exact contract class: the vectors were written by
// something that never saw this package's precedence code.
//
// The directory sits outside the module, so a consumer's module cache does not
// have it. These tests SKIP when it is absent and FAIL when it is absent but
// BRD14_REQUIRE_VECTORS=1 is set — as the root Makefile and CI do, so a moved
// or renamed corpus can never turn the whole family silently into skips.

import (
	"bytes"
	"encoding/hex"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

// vectorsDir is the shared corpus: the repository root's vectors/, one level
// above this module.
const vectorsDir = "../vectors"

// readVectors returns the data rows of one vectors file, split on TAB, after
// checking each has cols columns. Comment lines (#) and blank lines are not
// rows. A missing directory is reported as fs.ErrNotExist, so callers can tell
// "no corpus here" from a broken one.
func readVectors(name string, cols int) ([][]string, error) {
	if _, err := os.Stat(vectorsDir); err != nil {
		return nil, err
	}
	data, err := os.ReadFile(filepath.Join(vectorsDir, name))
	if err != nil {
		return nil, fmt.Errorf("the vectors directory exists but %s does not read: %w", name, err)
	}
	var rows [][]string
	for i, line := range strings.Split(string(data), "\n") {
		if line == "" || line[0] == '#' {
			continue
		}
		f := strings.Split(line, "\t")
		if len(f) != cols {
			return nil, fmt.Errorf("%s:%d: %d columns, want %d: %q", name, i+1, len(f), cols, line)
		}
		rows = append(rows, f)
	}
	return rows, nil
}

// vectorRows is readVectors under the skip/fail rule.
func vectorRows(tb testing.TB, name string, cols int) [][]string {
	tb.Helper()
	rows, err := readVectors(name, cols)
	switch {
	case errors.Is(err, fs.ErrNotExist) && os.Getenv("BRD14_REQUIRE_VECTORS") == "1":
		tb.Fatalf("BRD14_REQUIRE_VECTORS=1 but %s is absent: %v", vectorsDir, err)
	case errors.Is(err, fs.ErrNotExist):
		tb.Skipf("%s is absent (a published module carries no corpus): %v", vectorsDir, err)
	case err != nil:
		tb.Fatal(err)
	}
	return rows
}

// unhex decodes the corpus's byte notation: lowercase hex, "-" for empty.
func unhex(tb testing.TB, s string) []byte {
	tb.Helper()
	if s == "-" {
		return []byte{}
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		tb.Fatalf("bad hex %q: %v", s, err)
	}
	return b
}

func atou(tb testing.TB, s string) uint64 {
	tb.Helper()
	v, err := strconv.ParseUint(s, 10, 64)
	if err != nil {
		tb.Fatalf("bad unsigned %q: %v", s, err)
	}
	return v
}

// TestSharedVectorsValid: every accepted row through every entry point that
// reads or writes it — both encoders, both decoders, the hash and the field
// readers.
func TestSharedVectorsValid(t *testing.T) {
	rows := vectorRows(t, "valid.tsv", 8)
	if len(rows) < 4096 {
		t.Fatalf("valid.tsv has %d rows, want at least the 4096-row bench corpus", len(rows))
	}
	buf := make([]byte, 0, 64)
	for _, r := range rows {
		ns, snow, id := r[0], atou(t, r[1]), r[2]
		hash, ms, ts, node, seq := atou(t, r[3]), atou(t, r[4]), atou(t, r[5]), atou(t, r[6]), atou(t, r[7])

		if got, err := Encode(ns, snow); err != nil || got != id {
			t.Fatalf("Encode(%q, %d) = %q, %v; want %q", ns, snow, got, err, id)
		}
		var err error
		buf = append(buf[:0], "id="...)
		if buf, err = AppendEncode(buf, ns, snow); err != nil || string(buf) != "id="+id {
			t.Fatalf("AppendEncode(%q, %d) = %q, %v; want %q", ns, snow, buf, err, "id="+id)
		}
		if gns, gsnow, err := Parse(id); err != nil || gns != ns || gsnow != snow {
			t.Fatalf("Parse(%q) = %q, %d, %v; want %q, %d", id, gns, gsnow, err, ns, snow)
		}
		if gns, gsnow, err := ParseBytes([]byte(id)); err != nil || string(gns[:]) != ns || gsnow != snow {
			t.Fatalf("ParseBytes(%q) = %q, %d, %v; want %q, %d", id, gns[:], gsnow, err, ns, snow)
		}
		if d, err := Decode(id); err != nil || d != snow {
			t.Fatalf("Decode(%q) = %d, %v", id, d, err)
		}
		if d, err := DecodeBytes([]byte(id)); err != nil || d != snow {
			t.Fatalf("DecodeBytes(%q) = %d, %v", id, d, err)
		}
		if !Valid(id) || !ValidBytes([]byte(id)) {
			t.Fatalf("Valid/ValidBytes(%q) = %v/%v", id, Valid(id), ValidBytes([]byte(id)))
		}
		if got := Hash32(snow); uint64(got) != hash {
			t.Fatalf("Hash32(%d) = %d, want %d", snow, got, hash)
		}
		if got := UnixMs(snow); uint64(got) != ms {
			t.Fatalf("UnixMs(%d) = %d, want %d", snow, got, ms)
		}
		if snow>>22 != ts || NodeOf(snow) != node || SeqOf(snow) != seq {
			t.Fatalf("fields(%d) = %d/%d/%d, want %d/%d/%d", snow, snow>>22, NodeOf(snow), SeqOf(snow), ts, node, seq)
		}
		// The scan cursor for the row's own millisecond is the row with its
		// node and seq cleared: MinFor inverts UnixMs down to the field.
		if got := MinFor(time.UnixMilli(int64(ms))); got != ts<<22 {
			t.Fatalf("MinFor(%d ms) = %d, want %d", ms, got, ts<<22)
		}
	}
}

// TestSharedVectorsInvalid: every decode refusal, through every decode entry
// point, with the exact class the oracle assigned.
func TestSharedVectorsInvalid(t *testing.T) {
	rows := vectorRows(t, "invalid.tsv", 2)
	seen := map[string]int{}
	for _, r := range rows {
		b, class := unhex(t, r[0]), r[1]
		seen[class]++
		_, snow, err := Parse(string(b))
		if got := classOf(t, err); got != class || snow != 0 {
			t.Fatalf("Parse(%q) = %d, class %s; want class %s", b, snow, got, class)
		}
		ns, bsnow, berr := ParseBytes(b)
		if got := classOf(t, berr); got != class || bsnow != 0 || ns != [3]byte{} {
			t.Fatalf("ParseBytes(%q) = %q, %d, class %s; want class %s", b, ns[:], bsnow, got, class)
		}
		if _, derr := Decode(string(b)); derr != err {
			t.Fatalf("Decode(%q) = %v, want %v", b, derr, err)
		}
		if _, derr := DecodeBytes(b); derr != err {
			t.Fatalf("DecodeBytes(%q) = %v, want %v", b, derr, err)
		}
		if Valid(string(b)) || ValidBytes(b) {
			t.Fatalf("Valid/ValidBytes accepted %q", b)
		}
	}
	for _, c := range causes {
		if seen[c.class] == 0 {
			t.Errorf("invalid.tsv has no %s row — the corpus no longer covers every class", c.class)
		}
	}
}

// TestSharedVectorsEncodeInvalid: every encode refusal, through Encode and
// AppendEncode, and — for a namespace fault, which no snowflake can rescue —
// through the generator's two branded mints as well.
func TestSharedVectorsEncodeInvalid(t *testing.T) {
	rows := vectorRows(t, "encode_invalid.tsv", 3)
	g := NewGenerator(1)
	prefix := []byte("keep")
	for _, r := range rows {
		ns, snow, class := string(unhex(t, r[0])), atou(t, r[1]), r[2]
		id, err := Encode(ns, snow)
		if got := classOf(t, err); got != class || id != "" {
			t.Fatalf("Encode(%q, %d) = %q, class %s; want class %s", ns, snow, id, got, class)
		}
		dst := append(make([]byte, 0, 32), prefix...)
		out, aerr := AppendEncode(dst, ns, snow)
		if aerr != err || !bytes.Equal(out, prefix) || len(out) != len(prefix) {
			t.Fatalf("AppendEncode(%q, %d) = %q, %v; want dst unchanged and %v", ns, snow, out, aerr, err)
		}
		if class == "NAMESPACE" {
			if _, err := g.NextBranded(ns); err != ErrNamespace {
				t.Fatalf("NextBranded(%q) = %v, want ErrNamespace", ns, err)
			}
			if out, err := g.AppendNextBranded(dst, ns); err != ErrNamespace || !bytes.Equal(out, prefix) {
				t.Fatalf("AppendNextBranded(%q) = %q, %v; want dst unchanged and ErrNamespace", ns, out, err)
			}
		}
	}
}

// TestSharedVectorsNode: the node derivation over arbitrary host bytes,
// including the empty host and non-UTF-8 ones.
func TestSharedVectorsNode(t *testing.T) {
	for _, r := range vectorRows(t, "node.tsv", 3) {
		host, pid, want := string(unhex(t, r[0])), atou(t, r[1]), atou(t, r[2])
		if got := NodeFrom(host, int(pid)); got != want {
			t.Fatalf("NodeFrom(%q, %d) = %d, want %d", host, pid, got, want)
		}
	}
}
